"use client";

import { useReducedMotion } from "motion/react";
import {
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";

import { SparklesIcon, XIcon } from "@/components/blocks/parts/icons";
import { Switch } from "@/components/motion/switch";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { AddMemory } from "./agent-memory/add-memory";
import {
  INITIAL_MEMORIES,
  KIND_HUE,
  KIND_LABEL,
  KINDS,
  type Memory,
  type MemoryKind,
  PENDING_CAPTURE,
} from "./agent-memory/data";
import { FullnessMeter } from "./agent-memory/fullness-meter";
import { glideRow } from "./agent-memory/glide";
import { KindFilter, type KindFilterValue } from "./agent-memory/kind-filter";
import { MemoryRow } from "./agent-memory/memory-row";
import { SearchIcon } from "./icons";

interface Arrival {
  id: string;
  from: DOMRect;
}

/**
 * What an assistant remembers about one person: how full its memory is,
 * whether it may use it, and the notes grouped by kind. A note can be
 * edited, forgotten, captured from today's chat or added by hand, and a new
 * note glides from where it came from into its group.
 */
export function AgentMemory({ className }: { className?: string }) {
  const titleId = useId();
  const savedId = useId();
  const historyId = useId();
  const reduceMotion = useReducedMotion();

  const [memories, setMemories] = useState<Memory[]>(INITIAL_MEMORIES);
  const [pending, setPending] = useState<Memory | null>(PENDING_CAPTURE);
  const [latestId, setLatestId] = useState<string | null>(null);
  const [useSaved, setUseSaved] = useState(true);
  const [useHistory, setUseHistory] = useState(true);
  const [filter, setFilter] = useState<KindFilterValue>("all");
  const [searching, setSearching] = useState(false);
  const [query, setQuery] = useState("");
  const [forgotten, setForgotten] = useState<{
    memory: Memory;
    index: number;
  } | null>(null);
  const [message, setMessage] = useState("");
  const [arrival, setArrival] = useState<Arrival | null>(null);

  const rootRef = useRef<HTMLDivElement>(null);
  const pillRef = useRef<HTMLButtonElement>(null);
  const formRef = useRef<HTMLFormElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);
  const counter = useRef(0);
  const cancelGlide = useRef<(() => void) | null>(null);

  useEffect(() => () => cancelGlide.current?.(), []);
  useEffect(() => {
    if (searching) searchRef.current?.focus();
  }, [searching]);

  useLayoutEffect(() => {
    const root = rootRef.current;
    if (!arrival || !root) return;
    const row = root.querySelector<HTMLElement>(
      `[data-memory-id="${arrival.id}"]`,
    );
    setArrival(null);
    if (!row) return;
    row.scrollIntoView({ block: "nearest" });
    if (reduceMotion) return;
    cancelGlide.current?.();
    cancelGlide.current = glideRow(root, row, arrival.from);
  }, [arrival, reduceMotion]);

  const counts = useMemo(() => {
    const count = (kind: MemoryKind) => memories.filter((memory) => memory.kind === kind).length;
    return {
      all: memories.length,
      preference: count("preference"),
      work: count("work"),
      people: count("people"),
      schedule: count("schedule"),
    };
  }, [memories]);

  const needle = query.trim().toLowerCase();
  const visible = memories.filter(
    (memory) =>
      (filter === "all" || memory.kind === filter) &&
      (!needle || memory.text.toLowerCase().includes(needle)),
  );

  const insert = (memory: Memory, from: DOMRect | undefined) => {
    // The new note always lands in view: clear anything that would hide it.
    if (filter !== "all" && filter !== memory.kind) setFilter("all");
    setQuery("");
    setMemories((list) => {
      const at = list.findIndex((item) => item.kind === memory.kind);
      return at === -1
        ? [...list, memory]
        : [...list.slice(0, at), memory, ...list.slice(at)];
    });
    setLatestId(memory.id);
    setMessage(`Saved: ${memory.text}`);
    if (from) setArrival({ id: memory.id, from });
  };

  const capture = () => {
    if (!pending) return;
    insert(
      { ...pending, source: "From today's chat" },
      pillRef.current?.getBoundingClientRect(),
    );
    setPending(null);
  };

  const add = (text: string, kind: MemoryKind) => {
    counter.current += 1;
    insert(
      {
        id: `added-${counter.current}`,
        text,
        kind,
        source: "Added by you just now",
      },
      formRef.current?.getBoundingClientRect(),
    );
  };

  const forget = (memory: Memory) => {
    setForgotten({ memory, index: memories.indexOf(memory) });
    setMemories((list) => list.filter((item) => item.id !== memory.id));
    setMessage(`Forgot: ${memory.text}`);
  };

  const undoForget = () => {
    if (!forgotten) return;
    const { memory, index } = forgotten;
    setMemories((list) => [
      ...list.slice(0, index),
      memory,
      ...list.slice(index),
    ]);
    setForgotten(null);
    setMessage(`Restored: ${memory.text}`);
  };

  const save = (id: string, text: string) => {
    setMemories((list) =>
      list.map((item) =>
        item.id === id
          ? { ...item, text, source: "Edited by you just now" }
          : item,
      ),
    );
    setMessage("Note updated.");
  };

  const latest = memories.find((memory) => memory.id === latestId);
  const showLatest = () => {
    if (!latest) return;
    setFilter("all");
    setQuery("");
    requestAnimationFrame(() => {
      const row = rootRef.current?.querySelector<HTMLElement>(
        `[data-memory-id="${latest.id}"]`,
      );
      row?.scrollIntoView({ block: "nearest" });
      row?.querySelector<HTMLButtonElement>("button")?.focus();
    });
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div ref={rootRef} className="relative">
        <header className="flex flex-wrap items-start justify-between gap-x-8 gap-y-4 border-b border-border px-5 py-4">
          <div className="min-w-0">
            <h2 id={titleId} className="text-base font-semibold">
              What Fern remembers
            </h2>
            <p className="text-sm text-muted-foreground">
              Notes Fern keeps about you between chats.
            </p>
          </div>
          <FullnessMeter memories={memories} />
        </header>

        <div className="flex flex-col gap-3 border-b border-border px-5 py-4 @xl:flex-row @xl:gap-8">
          <label
            htmlFor={savedId}
            className="flex cursor-pointer items-center justify-between gap-3 text-sm @xl:justify-start"
          >
            Use saved memories
            <Switch
              id={savedId}
              checked={useSaved}
              onCheckedChange={setUseSaved}
            />
          </label>
          <label
            htmlFor={historyId}
            className="flex cursor-pointer items-center justify-between gap-3 text-sm @xl:justify-start"
          >
            Use chat history
            <Switch
              id={historyId}
              checked={useHistory}
              onCheckedChange={setUseHistory}
            />
          </label>
        </div>

        <div className="flex flex-col gap-3 px-5 pt-4">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <KindFilter value={filter} counts={counts} onChange={setFilter} />
            <Button
              variant={searching ? "secondary" : "ghost"}
              size="sm"
              aria-expanded={searching}
              onClick={() => {
                setSearching((open) => !open);
                setQuery("");
              }}
            >
              {searching ? (
                <XIcon aria-hidden="true" className="size-4" />
              ) : (
                <SearchIcon aria-hidden="true" className="size-4" />
              )}
              {searching ? "Close search" : "Search"}
            </Button>
          </div>
          {searching ? (
            <Input
              ref={searchRef}
              type="search"
              aria-label="Search notes"
              placeholder="Search notes"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Escape") setSearching(false);
              }}
            />
          ) : null}
          {pending || latest ? (
            <Button
              ref={pillRef}
              variant="outline"
              size="sm"
              className="h-auto min-h-8 max-w-full justify-start self-start text-left whitespace-normal"
              onClick={pending ? capture : showLatest}
            >
              <SparklesIcon
                aria-hidden="true"
                className="size-4 text-chart-1"
              />
              <span className="min-w-0">
                {pending ? (
                  <>
                    <span className="font-semibold">
                      Save from today&apos;s chat:
                    </span>{" "}
                    <span className="font-normal">{pending.text}</span>
                  </>
                ) : (
                  <>
                    <span className="font-semibold">Updated:</span>{" "}
                    <span className="font-normal">{latest?.text}</span>
                  </>
                )}
              </span>
            </Button>
          ) : null}
        </div>

        <div
          className={cn(
            "scroll-fade-effect-y scrollbar-none flex max-h-96 flex-col gap-4 overflow-y-auto px-2 py-4 motion-safe:transition-opacity",
            !useSaved && "opacity-50",
          )}
        >
          {!useSaved ? (
            <p className="px-3 text-sm text-muted-foreground">
              Fern will not use these notes in new chats.
            </p>
          ) : null}
          {KINDS.map((kind) => {
            const rows = visible.filter((memory) => memory.kind === kind);
            if (rows.length === 0) return null;
            return (
              <section
                key={kind}
                aria-label={KIND_LABEL[kind]}
                className="flex flex-col gap-0.5"
              >
                <h3 className="flex items-center gap-2 px-3 pb-1 text-xs font-medium text-muted-foreground">
                  <span
                    aria-hidden="true"
                    className={cn("h-3 w-1 rounded-full", KIND_HUE[kind])}
                  />
                  {KIND_LABEL[kind]}
                </h3>
                <ul className="flex flex-col">
                  {rows.map((memory) => (
                    <MemoryRow
                      key={memory.id}
                      memory={memory}
                      onSave={(text) => save(memory.id, text)}
                      onForget={() => forget(memory)}
                    />
                  ))}
                </ul>
              </section>
            );
          })}
          {visible.length === 0 ? (
            <p className="px-3 py-6 text-center text-sm text-muted-foreground">
              No notes match.
            </p>
          ) : null}
        </div>

        <div className="flex min-h-10 flex-wrap items-center gap-2 px-5 text-sm text-muted-foreground">
          <p role="status" className="min-w-0 flex-1 truncate">
            {message}
          </p>
          {forgotten ? (
            <Button
              variant="link"
              size="sm"
              className="h-7"
              onClick={undoForget}
            >
              Undo
            </Button>
          ) : null}
        </div>

        <AddMemory formRef={formRef} onAdd={add} />
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

