/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { type FormEvent, type RefObject, useId, useState } from "react";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";

import { KIND_SINGULAR, KINDS, type MemoryKind } from "./data";

/** Props for the field that adds a note by hand. */
export interface AddMemoryProps {
  /** The form element, so a new row can glide out of it. */
  formRef: RefObject<HTMLFormElement | null>;
  onAdd: (text: string, kind: MemoryKind) => void;
}

/** A field, a kind picker and an Add button. Enter adds the note. */
export function AddMemory({ formRef, onAdd }: AddMemoryProps) {
  const [text, setText] = useState("");
  const [kind, setKind] = useState<MemoryKind>("preference");
  const fieldId = useId();

  const submit = (event: FormEvent) => {
    event.preventDefault();
    const value = text.trim();
    if (!value) return;
    onAdd(value, kind);
    setText("");
  };

  return (
    <form ref={formRef} onSubmit={submit} className="flex flex-wrap items-center gap-2 border-t border-border px-5 py-4">
      <label htmlFor={fieldId} className="sr-only">
        A note for Fern to remember
      </label>
      <Input
        id={fieldId}
        value={text}
        onChange={(event) => setText(event.target.value)}
        placeholder="Add something for Fern to remember"
        className="min-w-0 flex-1 basis-56"
      />
      <Select value={kind} onValueChange={(value) => setKind(KINDS.find((option) => option === value) ?? "preference")}>
        <SelectTrigger aria-label="Kind of note" className="w-36">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {KINDS.map((option) => (
            <SelectItem key={option} value={option}>
              {KIND_SINGULAR[option]}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <Button type="submit" disabled={!text.trim()}>
        <PlusIcon aria-hidden="true" className="size-4" />
        Add
      </Button>
    </form>
  );
}

/** The kinds of note the assistant keeps. */
export type MemoryKind = "preference" | "work" | "people" | "schedule";

/** One note the assistant remembers about the person. */
export interface Memory {
  id: string;
  text: string;
  kind: MemoryKind;
  /** Where the note came from, such as a chat or the person typing it. */
  source: string;
}

/** The kinds in the order the list groups them. */
export const KINDS: MemoryKind[] = ["preference", "work", "people", "schedule"];

/** The plural name of each kind, for group headings and filters. */
export const KIND_LABEL = {
  preference: "Preferences",
  work: "Work",
  people: "People",
  schedule: "Schedule",
} satisfies Record<MemoryKind, string>;

/** The singular name of each kind, for the add field. */
export const KIND_SINGULAR = {
  preference: "Preference",
  work: "Work",
  people: "Person",
  schedule: "Schedule",
} satisfies Record<MemoryKind, string>;

/** The chart hue of each kind, used by the meter and the group markers. */
export const KIND_HUE = {
  preference: "bg-chart-1",
  work: "bg-chart-2",
  people: "bg-chart-3",
  schedule: "bg-chart-4",
} satisfies Record<MemoryKind, string>;

/** How many characters of notes the assistant can hold. */
export const CAPACITY = 1400;

/** The notes the block starts with. */
export const INITIAL_MEMORIES: Memory[] = [
  { id: "m1", text: "Prefers short replies with the booking link at the end.", kind: "preference", source: "From a chat on Nov 3" },
  { id: "m2", text: "Writes to patients in a warm, first-name tone.", kind: "preference", source: "From a chat on Oct 28" },
  { id: "m3", text: "Runs the front desk at the Harbour Street clinic.", kind: "work", source: "Added by you on Oct 12" },
  { id: "m4", text: "Tracks no-shows every Monday for the weekly team meeting.", kind: "work", source: "From a chat on Oct 20" },
  { id: "m5", text: "Dr. Amara Osei sees knee and hip follow-ups.", kind: "people", source: "From a chat on Oct 30" },
  { id: "m6", text: "Lena Brandt covers the desk on Thursday afternoons.", kind: "people", source: "From a chat on Nov 1" },
  { id: "m7", text: "Room 3 is kept free on Wednesdays for physiotherapy.", kind: "schedule", source: "From a chat on Oct 22" },
];

/** The note the assistant picked up in today's chat and has not saved yet. */
export const PENDING_CAPTURE: Memory = {
  id: "m-capture",
  text: "Books Friday follow-ups before 11 a.m. when possible.",
  kind: "schedule",
  source: "From today's chat",
};

import { RollingText } from "@/components/blocks/parts/rolling-text";
import { cn } from "@/lib/utils";

import { CAPACITY, KIND_HUE, KIND_LABEL, KINDS, type Memory } from "./data";
import type { VarStyle } from "@/components/blocks/lib/css-vars";

/**
 * How full the assistant's memory is, as one bar split by kind. Each kind
 * keeps its chart colour, and the legend names it, so colour never stands alone.
 */
export function FullnessMeter({ memories }: { memories: Memory[] }) {
  const used = memories.reduce((sum, memory) => sum + memory.text.length, 0);
  const percent = Math.min(100, Math.round((used / CAPACITY) * 100));
  return (
    <div className="flex w-full flex-col gap-2 @xl:w-64">
      <div className="flex items-baseline justify-between gap-2 text-sm">
        <span className="text-muted-foreground">Memory used</span>
        <span className="font-medium">
          <RollingText text={`${percent}%`} />
        </span>
      </div>
      <div
        role="progressbar"
        aria-label="Memory used"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        className="flex h-2 w-full gap-0.5 overflow-hidden rounded-full bg-muted"
      >
        {KINDS.map((kind) => {
          const share = memories.filter((memory) => memory.kind === kind).reduce((sum, memory) => sum + memory.text.length, 0);
          const barStyle: VarStyle = { "--w": `${(share / CAPACITY) * 100}%` };
          return (
            <span
              key={kind}
              className={cn("h-full w-(--w) rounded-full motion-safe:transition-all motion-safe:duration-500", KIND_HUE[kind])}
              style={barStyle}
            />
          );
        })}
      </div>
      <ul className="flex flex-wrap gap-x-3 gap-y-1 text-xs text-muted-foreground">
        {KINDS.map((kind) => (
          <li key={kind} className="flex items-center gap-1.5">
            <span aria-hidden="true" className={cn("size-2 rounded-full", KIND_HUE[kind])} />
            {KIND_LABEL[kind]}
          </li>
        ))}
      </ul>
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

const REM = 16;
const EASE = "cubic-bezier(0.22, 1, 0.36, 1)";
const DURATION = 520;

/**
 * Lifts a copy of a new row off `from` and glides it to the row's place,
 * by transform only, while the row's slot opens beneath it. The real row
 * stays hidden until the copy lands. Returns a function that cancels the
 * flight and puts everything back.
 */
export function glideRow(root: HTMLElement, row: HTMLElement, from: DOMRect): () => void {
  const rootBox = root.getBoundingClientRect();
  const target = row.getBoundingClientRect();
  const height = target.height / REM;

  const ghost = row.cloneNode(true);
  if (!(ghost instanceof HTMLElement)) return () => {};
  ghost.setAttribute("aria-hidden", "true");
  ghost.removeAttribute("data-memory-id");
  ghost.querySelectorAll("button, input, a").forEach((node) => node.setAttribute("tabindex", "-1"));
  Object.assign(ghost.style, {
    position: "absolute",
    left: `${(target.left - rootBox.left) / REM}rem`,
    top: `${(target.top - rootBox.top) / REM}rem`,
    width: `${target.width / REM}rem`,
    margin: "0",
    pointerEvents: "none",
    zIndex: "20",
    listStyle: "none",
  });
  ghost.classList.add("bg-card", "shadow-lg", "ring-1", "ring-border");
  root.append(ghost);

  const dx = (from.left - target.left) / REM;
  const dy = (from.top + from.height / 2 - (target.top + target.height / 2)) / REM;
  row.style.opacity = "0";

  const flight = ghost.animate(
    [
      { transform: `translate(${dx}rem, ${dy}rem) scale(0.96)`, opacity: 0.6 },
      { transform: "translate(0, 0) scale(1)", opacity: 1 },
    ],
    { duration: DURATION, easing: EASE },
  );
  const slot = row.animate([{ height: "0rem" }, { height: `${height}rem` }], { duration: DURATION * 0.7, easing: EASE });

  const finish = () => {
    ghost.remove();
    row.style.opacity = "";
  };
  flight.onfinish = finish;
  return () => {
    flight.cancel();
    slot.cancel();
    finish();
  };
}

