import { type KeyboardEvent, useRef } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { KIND_HUE, KIND_LABEL, KINDS, type MemoryKind } from "./data";

/** A filter value: one kind, or every kind. */
export type KindFilterValue = MemoryKind | "all";

const OPTIONS: KindFilterValue[] = ["all", ...KINDS];

/**
 * Pills that filter the notes by kind. They form one radio group: Tab lands
 * on the selected pill, and the arrows, Home and End move the selection.
 */
export function KindFilter({
  value,
  counts,
  onChange,
}: {
  value: KindFilterValue;
  counts: Record<KindFilterValue, number>;
  onChange: (value: KindFilterValue) => void;
}) {
  const refs = useRef<(HTMLButtonElement | null)[]>([]);

  const move = (index: number) => {
    const next = (index + OPTIONS.length) % OPTIONS.length;
    onChange(OPTIONS[next]!);
    refs.current[next]?.focus();
  };

  const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
    const key = event.key;
    const target =
      key === "ArrowRight" || key === "ArrowDown"
        ? index + 1
        : key === "ArrowLeft" || key === "ArrowUp"
          ? index - 1
          : key === "Home"
            ? 0
            : key === "End"
              ? OPTIONS.length - 1
              : undefined;
    if (target === undefined) return;
    event.preventDefault();
    move(target);
  };

  return (
    <div role="radiogroup" aria-label="Show notes of kind" className="flex flex-wrap gap-1.5">
      {OPTIONS.map((option, index) => {
        const checked = option === value;
        return (
          <Button
            key={option}
            ref={(node) => {
              refs.current[index] = node;
            }}
            role="radio"
            aria-checked={checked}
            tabIndex={checked ? 0 : -1}
            size="sm"
            variant={checked ? "secondary" : "ghost"}
            className="h-7"
            onClick={() => onChange(option)}
            onKeyDown={(event) => onKeyDown(event, index)}
          >
            {option === "all" ? null : <span aria-hidden="true" className={cn("size-1.5 rounded-full", KIND_HUE[option])} />}
            {option === "all" ? "All" : KIND_LABEL[option]}
            <span className="text-muted-foreground tabular-nums">{counts[option]}</span>
          </Button>
        );
      })}
    </div>
  );
}

