import { type KeyboardEvent, useEffect, useRef, useState } from "react";

import { TrashIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { cn } from "@/lib/utils";

import { PencilIcon } from "../icons";
import { KIND_HUE, type Memory } from "./data";

/** Props for one remembered note. */
export interface MemoryRowProps {
  memory: Memory;
  onSave: (text: string) => void;
  onForget: () => void;
}

/**
 * One note in the list. Its source and its Edit and Forget actions show
 * while the row has focus or the pointer, and always on a touch screen.
 * Edit swaps the text for a field: Enter saves and Escape cancels.
 */
export function MemoryRow({ memory, onSave, onForget }: MemoryRowProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(memory.text);
  const field = useRef<HTMLInputElement>(null);
  const editButton = useRef<HTMLButtonElement>(null);
  const returnFocus = useRef(false);

  useEffect(() => {
    if (editing) field.current?.select();
    else if (returnFocus.current) {
      returnFocus.current = false;
      editButton.current?.focus();
    }
  }, [editing]);

  const finish = (save: boolean) => {
    const text = draft.trim();
    if (save && text) onSave(text);
    else setDraft(memory.text);
    returnFocus.current = true;
    setEditing(false);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.nativeEvent.isComposing || event.keyCode === 229) return;
    if (event.key === "Enter") {
      event.preventDefault();
      finish(true);
    } else if (event.key === "Escape") {
      event.preventDefault();
      finish(false);
    }
  };

  return (
    <li data-memory-id={memory.id} className="group relative isolate flex items-start gap-3 rounded-lg px-3 py-2.5">
      <span aria-hidden="true" className="absolute inset-0 -z-10 rounded-lg group-focus-within:bg-muted/60 group-hover:bg-muted/40" />
      <span aria-hidden="true" className={cn("mt-1.5 size-2 shrink-0 rounded-full", KIND_HUE[memory.kind])} />
      <div className="flex min-w-0 flex-1 flex-col gap-1">
        {editing ? (
          <Input
            ref={field}
            aria-label="Edit note"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={onKeyDown}
            onBlur={() => editing && finish(true)}
            className="h-8"
          />
        ) : (
          <p className="text-sm">{memory.text}</p>
        )}
        <p
          className={cn(
            "text-xs text-muted-foreground opacity-0 group-focus-within:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100",
            "motion-safe:transition-opacity",
          )}
        >
          {memory.source}
        </p>
      </div>
      <div
        className={cn(
          "flex shrink-0 gap-0.5 opacity-0 group-focus-within:opacity-100 group-hover:opacity-100 [@media(hover:none)]:opacity-100",
          "motion-safe:transition-opacity",
        )}
      >
        <Button
          ref={editButton}
          variant="ghost"
          size="icon"
          className="size-7"
          aria-label={`Edit: ${memory.text}`}
          onClick={() => (editing ? finish(true) : setEditing(true))}
        >
          <PencilIcon aria-hidden="true" className="size-3.5" />
        </Button>
        <Button variant="ghost" size="icon" className="size-7" aria-label={`Forget: ${memory.text}`} onClick={onForget}>
          <TrashIcon aria-hidden="true" className="size-3.5" />
        </Button>
      </div>
    </li>
  );
}

